import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class SetMOFlag(object):

    def set_mo_flag_iphy_aashell(self, name, rrh_id, value, delay=0, mode=3, cell_class_id='Tx', how_many='-1'):
        """
        Execute set_mo_flag in iphy aashell cli
        set_mo_flag rrhid classId <1:create|2=update|3=both> [distName='' delay [OK=1|NOK=0]]

        :param str name: alias name
        :param str rrh_id: iphy radio head id
        :param str value: OK=1, NOK=0
        :param int delay: after this time in ms RP1:modifyParameterResp will be send. [ms]
        :param int mode: <1:create|2=update|3=both>
        :param str cell_class_id: iphy cell class id [Tx, Rx]
        :param int how_many: how many message should be delayed or failed, -1 means infinity
        """
        self._assert_command_available_in_help(name, "help", "set_mo_flag")
        command = 'set_mo_flag {rrh_id} {Tx_Rx} {mode} "" {delay} {value} {how_many}'.format(
            rrh_id=rrh_id, Tx_Rx=cell_class_id, mode=mode, delay=delay, value=value, how_many=how_many
        )
        output = self.execute_aashell_command(name, command)
        if output != ' ':
            raise Exception(output)
